import{_ as t,c as a,o as r,a2 as s}from"./chunks/framework.DkPtUiZm.js";const m=JSON.parse('{"title":"Suivi des mises à jour","description":"","frontmatter":{},"headers":[],"relativePath":"contribuer/backlog.md","filePath":"contribuer/backlog.md","lastUpdated":1795438092000}'),i={name:"contribuer/backlog.md"};function n(o,e,d,l,p,u){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="suivi-des-mises-a-jour" tabindex="-1">Suivi des mises à jour <a class="header-anchor" href="#suivi-des-mises-a-jour" aria-label="Permalink to &quot;Suivi des mises à jour&quot;">​</a></h1><p>État au <strong>22 novembre 2026</strong>. La version <strong>0.14.0 est préparée dans le dépôt</strong> ; ce document n’atteste pas sa publication sur npm. Les changements exacts et leur utilité sont décrits dans les journaux des paquets, sans recopier les mêmes lots à plusieurs endroits.</p><h2 id="changements-regroupes-pour-0-14-0" tabindex="-1">Changements regroupés pour 0.14.0 <a class="header-anchor" href="#changements-regroupes-pour-0-14-0" aria-label="Permalink to &quot;Changements regroupés pour 0.14.0&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Paquet</th><th>Contenu réellement modifié</th><th>Détail</th></tr></thead><tbody><tr><td>react-native</td><td>Rendu Uniwind, composants et variantes, formulaires/clavier, dates, navigation/session, listes/CRUD, adaptations tactiles et démonstration</td><td><a href="https://github.com/BeatJo/sia-ui/blob/main/packages/react-native/CHANGELOG.md#0140" target="_blank" rel="noreferrer">123 fiches regroupées par famille, contrats et limites</a></td></tr><tr><td>react-web</td><td>Rail flottant Sidebar/AppShell, icônes partagées, Spinner double-ring, contrat ResourceDefinition et catalogue de démonstration</td><td><a href="https://github.com/BeatJo/sia-ui/blob/main/packages/react-web/CHANGELOG.md#0140" target="_blank" rel="noreferrer">Changements par composant</a></td></tr><tr><td>headless</td><td>Contrat de ressource commun, permissions, requêtes annulables et tri explicite</td><td><a href="https://github.com/BeatJo/sia-ui/blob/main/packages/headless/CHANGELOG.md#0140" target="_blank" rel="noreferrer">API et utilité</a></td></tr><tr><td>tokens</td><td>41 tracés d’icônes partagés et types publics</td><td><a href="https://github.com/BeatJo/sia-ui/blob/main/packages/tokens/CHANGELOG.md#0140" target="_blank" rel="noreferrer">Catalogue d’icônes</a></td></tr><tr><td>utils</td><td>Repli des dates relatives en l’absence de Intl.RelativeTimeFormat</td><td><a href="https://github.com/BeatJo/sia-ui/blob/main/packages/utils/CHANGELOG.md#0140" target="_blank" rel="noreferrer">Correction Hermes</a></td></tr><tr><td>registry</td><td>Versions 0.14.0 des entrées sidebar, app-shell, icons, resource et spinner</td><td><a href="https://github.com/BeatJo/sia-ui/blob/main/packages/registry/CHANGELOG.md#0140" target="_blank" rel="noreferrer">Changements des fichiers copiables</a></td></tr><tr><td>api, cli, react, realtime-server</td><td>Alignement de version et, selon le paquet, de dépendances internes ; aucune nouvelle API propre</td><td><a href="https://github.com/BeatJo/sia-ui/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">Vue de la livraison</a></td></tr></tbody></table><p><strong>123 fiches natives</strong> et <strong>115 modules web</strong> mesurent deux inventaires différents. Une fiche peut regrouper des alias et un module plusieurs exports. La <a href="./parite-web-mobile.html">matrice de couverture</a> compare les responsabilités ; elle ne promet pas une identité de props, de variantes ou de fonctionnalités de bureau.</p><h2 id="deja-livre-dans-la-serie-0-13-0" tabindex="-1">Déjà livré dans la série 0.13.0 <a class="header-anchor" href="#deja-livre-dans-la-serie-0-13-0" aria-label="Permalink to &quot;Déjà livré dans la série 0.13.0&quot;">​</a></h2><p>Ces fonctions étaient incorrectement encore marquées « prochaine publication » dans l’ancien suivi. Elles ne sont pas des nouveautés de 0.14.0.</p><table tabindex="0"><thead><tr><th>Paquet</th><th>Fonctions concernées</th><th>Journal</th></tr></thead><tbody><tr><td>api</td><td>Liaison temps réel typée, salons Socket.IO avec reprise et fetchStreamSource</td><td><a href="https://github.com/BeatJo/sia-ui/blob/main/packages/api/CHANGELOG.md#0130" target="_blank" rel="noreferrer">0.13.0</a></td></tr><tr><td>headless</td><td>usePollUntil, useRealtimeRoom et traductions de confirmation exacte</td><td><a href="https://github.com/BeatJo/sia-ui/blob/main/packages/headless/CHANGELOG.md#0130" target="_blank" rel="noreferrer">0.13.0</a></td></tr><tr><td>realtime-server</td><td>Passerelle authentifiée, salons, reprise bornée, fanout injectable, présence, cadence et withIdempotentClaim</td><td><a href="https://github.com/BeatJo/sia-ui/blob/main/packages/realtime-server/CHANGELOG.md#0130" target="_blank" rel="noreferrer">0.13.0</a></td></tr><tr><td>utils</td><td>pollUntil, normalisation du téléphone, navigationLinks et diffLines</td><td><a href="https://github.com/BeatJo/sia-ui/blob/main/packages/utils/CHANGELOG.md#0130" target="_blank" rel="noreferrer">0.13.0</a></td></tr><tr><td>tokens</td><td>javascriptTokens et presets Tailwind/NativeWind</td><td><a href="https://github.com/BeatJo/sia-ui/blob/main/packages/tokens/CHANGELOG.md#0130" target="_blank" rel="noreferrer">0.13.0</a></td></tr><tr><td>react-web / registry</td><td>Confirmation facultative par saisie exacte</td><td><a href="https://github.com/BeatJo/sia-ui/blob/main/packages/react-web/CHANGELOG.md#0130" target="_blank" rel="noreferrer">ConfirmDialog</a></td></tr></tbody></table><h2 id="preparation-de-publication-—-19-novembre-2026" tabindex="-1">Préparation de publication — 19 novembre 2026 <a class="header-anchor" href="#preparation-de-publication-—-19-novembre-2026" aria-label="Permalink to &quot;Préparation de publication — 19 novembre 2026&quot;">​</a></h2><ul><li><strong>QRCode / qrcode-generator</strong> : l’encodeur est maintenant un pair requis, déclaré aussi en développement pour les tests ; la démo Expo l’installe explicitement. Les bundles ESM/CommonJS gardent cet import externe.</li><li><strong>Utilité</strong> : respecte la convention du dépôt et permet à l’application de maîtriser la dépendance JavaScript, sans changer le rendu ou l’encodage QR.</li><li><strong>Installation</strong> : <code>pnpm add qrcode-generator@^2.0.4</code> dans l’application native. Voir le <a href="./../guides/adaptations-mobiles.html">guide des adaptations</a>.</li><li><strong>Contrôles validés</strong> : dépendances, licences, journaux/versions du registre, synchronisation des README, 335 tests natifs, typage du paquet et de la démo, construction des paquets et des démonstrations web/documentation.</li><li><strong>Distribution vérifiée</strong> : archive 0.14.0 avec pair QR requis, imports externes ESM/CommonJS et dépendances workspace converties en versions publiables.</li><li><strong>Export Expo validé</strong> : bundles Android, iOS et web générés. L’export est lancé directement avec un cache temporaire dans l’environnement cloud ; ces bundles ne remplacent pas la vérification physique du BottomSheet ci-dessous.</li></ul><h2 id="demo-google-play-—-preparation-du-22-novembre-2026" tabindex="-1">Démo Google Play — préparation du 22 novembre 2026 <a class="header-anchor" href="#demo-google-play-—-preparation-du-22-novembre-2026" aria-label="Permalink to &quot;Démo Google Play — préparation du 22 novembre 2026&quot;">​</a></h2><ul><li><p><strong>Android</strong> : identifiant proposé com.jodemi.siauidemo, nom SIA UI Demo, icône SIA existante, version 1.0.0 et sauvegarde automatique désactivée.</p></li><li><p><strong>Permissions</strong> : caméra à la demande, blocage du microphone et des accès globaux aux médias et de superposition ; sélecteurs système pour photos et documents.</p></li><li><p><strong>Thème système</strong> : ajout du module officiel expo-system-ui pour le mode automatique en application autonome, validé dans les ressources Android générées.</p></li><li><p><strong>Build monorepo</strong> : profils EAS APK/AAB, construction des packages locaux après installation et numéro de build distant incrémenté en production.</p></li><li><p><strong>Confidentialité</strong> : route publique dans l’app et texte pour une page HTTPS ; données locales et session de démonstration explicitement décrites.</p></li><li><p><strong>Store</strong> : guide pas à pas et proposition de fiche. Compte Expo/projet EAS, compte Google Play, identité de l’éditeur, visuels finaux, tests sur APK signé, AAB et premier envoi restent à réaliser avec les comptes réels.</p></li><li><p><strong>Vérifications réalisées</strong> : schéma EAS officiel, génération Android (identifiant, nom, thème système, sauvegarde et retrait des permissions), hook de construction monorepo, typage/lint de la démo, exports Android/iOS/web et site documentaire. Aucun APK/AAB signé ni validation sur téléphone n’est annoncé à ce stade.</p></li></ul><p>Voir le <a href="./../guides/publication-google-play.html">guide Google Play</a>. Cette préparation ne constitue pas une publication de l’application ni une nouvelle version npm.</p><h2 id="validation-a-terminer" tabindex="-1">Validation à terminer <a class="header-anchor" href="#validation-a-terminer" aria-label="Permalink to &quot;Validation à terminer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Priorité</th><th>Vérification concrète</th><th>Résultat attendu / utilité</th></tr></thead><tbody><tr><td>P1</td><td>Dernière présentation de BottomSheet sur téléphone : ouverture, glissement, crans, fermeture après clavier, contenu long et actions fixes</td><td>Confirmer l’absence de saut de hauteur, de marge extérieure en mode edge et d’action masquée. <a href="./../guides/bottom-sheet-mobile.html">Scénarios et réglages</a>.</td></tr><tr><td>P1</td><td>Parcours clavier et navigation sur iOS et Android, grands textes, VoiceOver/TalkBack et réduction des mouvements</td><td>Vérifier les particularités d’appareil que les tests et exports ne démontrent pas.</td></tr><tr><td>P2</td><td>Longues listes sur appareil : recherche, filtres, sélection et rafraîchissement</td><td>Observer fluidité et consommation mémoire avec des données représentatives.</td></tr></tbody></table><p>Les essais utilisateur des lots précédents sont confirmés dans la conversation. La dernière modification de BottomSheet n’a pas encore de confirmation physique consignée. Les vérifications automatisées et les exports ne constituent pas une certification de tous les appareils.</p><h2 id="evolutions-proposees-—-non-implementees" tabindex="-1">Évolutions proposées — non implémentées <a class="header-anchor" href="#evolutions-proposees-—-non-implementees" aria-label="Permalink to &quot;Évolutions proposées — non implémentées&quot;">​</a></h2><p>Ces pistes répondent à des limites identifiées ; elles ne sont ni une promesse ni des fonctionnalités livrées. Les adaptateurs déjà prévus restent utilisables.</p><table tabindex="0"><thead><tr><th>Priorité proposée</th><th>Élément</th><th>Travail précis et utilité</th></tr></thead><tbody><tr><td>P2</td><td>defaults natifs</td><td>Étendre les clés de defaults aux composants qui ne les consomment pas encore ; permettre un réglage global plus homogène, sans prétendre que toutes les props sont déjà centralisées.</td></tr><tr><td>P2</td><td>Ressources distantes</td><td>Concevoir pagination par curseur, cache et invalidation temps réel ; éviter les rechargements complets pour les grosses collections.</td></tr><tr><td>P2</td><td>Sélection serveur</td><td>Définir un contrat « tous les résultats de la requête sauf exclusions » ; dépasser allKeys explicite sans supposer que les lignes non chargées sont connues.</td></tr><tr><td>P3</td><td>Tree / TreeSelect</td><td>Chargement paresseux de branches et politique explicite de cascade ; adapter les très grandes hiérarchies sans changer silencieusement la sélection existante.</td></tr><tr><td>P3</td><td>Dates</td><td>Définir un contrat optionnel de fuseau métier et d’ambiguïtés de changement d’heure ; les valeurs civiles actuelles n’assurent pas cette conversion.</td></tr><tr><td>P3</td><td>Chart / EventCalendar</td><td>Évaluer zoom, second axe ou manipulation avancée du planning selon un besoin réel ; conserver une interaction mobile accessible.</td></tr></tbody></table><h2 id="responsabilites-de-l-application" tabindex="-1">Responsabilités de l’application <a class="header-anchor" href="#responsabilites-de-l-application" aria-label="Permalink to &quot;Responsabilités de l’application&quot;">​</a></h2><ul><li>Fournir les sources réseau, le stockage, les droits serveur et la persistance de session.</li><li>Brancher les adaptateurs de fichiers/caméra, presse-papiers et partage d’image QR selon la plateforme.</li><li>Choisir un moteur d’aperçu Markdown et un adaptateur de texte riche ; nettoyer le HTML.</li><li>Préparer routes et défilement d’un Tour, puis conserver son état si nécessaire.</li></ul><p>Ces points sont des frontières d’intégration documentées, pas des composants absents. Voir les <a href="./../guides/react-native.html">guides mobiles</a> et la <a href="./changelogs.html">convention de changelog</a> pour tenir ce suivi à jour.</p>',22)])])}const h=t(i,[["render",n]]);export{m as __pageData,h as default};
